#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    const char *s = (argc >= 2) ? argv[1] : "";
    // Simple stack for expected closing characters
    char stack[1024];
    int top = 0;
    int balanced = 1;
    for (size_t i = 0; i < strlen(s); ++i) {
        char c = s[i];
        if (c == '(') {
            if (top >= (int)sizeof(stack)) { balanced = 0; break; }
            stack[top++] = ')';
        } else if (c == '[') {
            if (top >= (int)sizeof(stack)) { balanced = 0; break; }
            stack[top++] = ']';
        } else if (c == '{') {
            if (top >= (int)sizeof(stack)) { balanced = 0; break; }
            stack[top++] = '}';
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0 || stack[top-1] != c) { balanced = 0; break; }
            --top;
        }
        // ignore other characters
    }
    if (top != 0) balanced = 0;
    puts(balanced ? "BALANCED" : "UNBALANCED");
    return 0;
}
